        if (intermediateOutputRoot(intermediateOutputRootsCount() - 1) != rootClaim().raw()) {
            revert IntermediateRootMismatch(
                intermediateOutputRoot(intermediateOutputRootsCount() - 1), rootClaim().raw()
            );
        }

