            tstore(TSLOT_MIN_AMOUNT_OUT, minAmountOut)
            tstore(TSLOT_TIP_BPS,        tipBps)
        }
        // Pass fork structure data through unlock
        poolManager.unlock(abi.encode(preForkPath, forkPoints, postForkPath));
    }

