            address(this),
            zeroForOne,
            int256(loanAmount),       // positive = exact input
            sqrtPriceLimitX96,
            cbData
        );

        uint256 balAfter = IERC20(flashToken).balanceOf(address(this));
        uint256 profit = balAfter - balBefore;
