function commitJudgmentEth(
        uint256 roundId,
        uint256 judgmentId,
        address owner,
        uint256 entryAmount,
        uint256 maxReservedPayout
    ) external payable nonReentrant onlyArena {
        if (asset != ETH_ASSET) {
            revert InvalidAsset();
        }
        if (msg.value != entryAmount) {
            revert InvalidAmount();
        }

        _commitJudgment(
            roundId,
            judgmentId,
            owner,
            entryAmount,
            maxReservedPayout,
            maxReservedPayout,
            false
        );
        poolVault.receiveBusinessEth{value: entryAmount}(
            entryAmount,
            maxReservedPayout
        );
    }

