constructor(address impl, address initialOwner, address initialFeeWallet, address initialOfficer)
        Ownable(initialOwner)
    {
        if (impl == address(0) || initialFeeWallet == address(0) || initialOfficer == address(0)) revert ZeroAddress();
        implementation = impl;
        feeWallet = initialFeeWallet;
        isCompliance[initialOfficer] = true;
        emit FeeWalletUpdated(address(0), initialFeeWallet);
        emit OfficerAdded(initialOfficer);
    }

function createEscrow(
        bytes32 dealId,
        address seller,
        address token,
        uint256 amount,
        address[] calldata cosigners,
        uint8 threshold,
        MettaPayMilestoneEscrow.MilestoneInput[] calldata milestones,
        address notifyOfficer
    ) external payable whenNotPaused returns (address escrow) {
        if (getClone[dealId] != address(0)) revert DealAlreadyExists();
        if (amount == 0) revert AmountMismatch();
        if (token != address(0) && !isSupportedToken[token]) revert TokenNotSupported();
        if (notifyOfficer != address(0) && !isCompliance[notifyOfficer]) revert ZeroAddress();

        // Deterministic clone — predictable address per dealId for off-chain UX.
        escrow = Clones.cloneDeterministic(implementation, dealId);
        getClone[dealId] = escrow;

        // Move the funds into the clone, then initialize.
        if (token == address(0)) {
            if (msg.value != amount) revert AmountMismatch();
        } else {
            if (msg.value != 0) revert NotEth();
            IERC20(token).safeTransferFrom(msg.sender, escrow, amount);
        }

        MettaPayMilestoneEscrow.InitParams memory p = MettaPayMilestoneEscrow.InitParams({
            dealId: dealId,
            buyer: msg.sender,
            seller: seller,
            token: token,
            amount: amount,
            cosigners: cosigners,
            threshold: threshold,
            milestones: milestones,
            notifyOfficer: notifyOfficer,
            feeWallet: feeWallet,
            depositFeeBps: depositFeeBps,
            releaseFeeBps: releaseFeeBps,
            recallFeeBps: recallFeeBps
        });

        // For native ETH, forward the value to the clone's initialize().
        if (token == address(0)) {
            MettaPayMilestoneEscrow(payable(escrow)).initialize{value: amount}(p);
        } else {
            MettaPayMilestoneEscrow(payable(escrow)).initialize(p);
        }

        emit EscrowCreated(dealId, escrow, msg.sender, seller, token, amount, notifyOfficer);
    }

function initialize(InitParams calldata p) external payable nonReentrant {
        if (_initialized) revert AlreadyInitialized();
        _initialized = true;
        factory = msg.sender;

        if (p.dealId == bytes32(0)) revert DealNotFound();
        if (p.buyer == address(0) || p.seller == address(0)) revert ZeroAddress();
        if (p.buyer == p.seller) revert SelfDeal();
        if (p.amount == 0) revert AmountMismatch();
        if (p.cosigners.length == 0 || p.cosigners.length > MAX_COSIGNERS) revert TooManyCosigners();
        if (p.threshold == 0 || p.threshold > p.cosigners.length) revert InvalidThreshold();
        if (p.milestones.length == 0) revert NoMilestones();
        if (p.milestones.length > MAX_MILESTONES) revert TooManyMilestones();
        if (p.feeWallet == address(0)) revert ZeroAddress();

        // Funds must already be inside this contract (factory transferred them).
        if (p.token == address(0)) {
            if (msg.value != p.amount) revert AmountMismatch();
        } else {
            if (msg.value != 0) revert NotEth();
            // Defense-in-depth: the factory has already done safeTransferFrom
            // to address(this); we trust it for accounting but a sanity check
            // would cost gas with no real benefit.
        }

        dealId        = p.dealId;
        buyer         = p.buyer;
        seller        = p.seller;
        token         = p.token;
        grossAmount   = p.amount;
        feeWallet     = p.feeWallet;
        depositFeeBps = p.depositFeeBps;
        releaseFeeBps = p.releaseFeeBps;
        recallFeeBps  = p.recallFeeBps;
        notifyOfficer = p.notifyOfficer;

        uint256 depFee = (p.amount * p.depositFeeBps) / BPS_DENOM;
        uint256 escrowed = p.amount - depFee;
        escrowedRemaining = escrowed;
        threshold = p.threshold;
        milestoneCount = uint8(p.milestones.length);
        openMilestones = uint8(p.milestones.length);
        status = DealStatus.ACTIVE;
        createdAt = uint64(block.timestamp);

        for (uint256 i = 0; i < p.cosigners.length; i++) {
            address c = p.cosigners[i];
            if (c == address(0)) revert ZeroAddress();
            if (c == p.buyer || c == p.seller) revert PartyConflict();
            if (isCosigner[c]) revert DuplicateCosigner();
            isCosigner[c] = true;
            _cosigners.push(c);
        }

        uint16 pctSum = 0;
        uint256 escAssigned = 0;
        uint256 grossAssigned = 0;
        for (uint256 i = 0; i < p.milestones.length; i++) {
            MilestoneInput calldata mi = p.milestones[i];
            if (mi.pctBps == 0) revert BadPctSum();
            pctSum += mi.pctBps;
            Milestone storage m = _milestones[uint8(i)];
            if (i + 1 == p.milestones.length) {
                m.escrowedAmount = escrowed - escAssigned;
                m.grossShare = p.amount - grossAssigned;
            } else {
                uint256 escShare = (escrowed * mi.pctBps) / BPS_DENOM;
                uint256 grossShare = (p.amount * mi.pctBps) / BPS_DENOM;
                m.escrowedAmount = escShare;
                m.grossShare = grossShare;
                escAssigned += escShare;
                grossAssigned += grossShare;
            }
            m.deadline = mi.deadline;
            m.requiresCompliance = mi.requiresCompliance;
            m.status = MStatus.PENDING;
        }
        if (pctSum != BPS_DENOM) revert BadPctSum();

        if (depFee > 0) {
            _payOut(p.token, p.feeWallet, depFee);
            emit FeeCollected(p.dealId, type(uint8).max, keccak256("deposit"), p.token, depFee);
        }

        emit DealFunded(
            p.dealId, p.buyer, p.seller, p.token, p.amount, escrowed,
            p.threshold, uint8(p.milestones.length), p.notifyOfficer
        );
    }

constructor(

        string memory _name,

        string memory _symbol,

        uint256       _totalSupply,

        uint256       _startingMaxWalletBps,

        uint256       _growthBpsPerSecond

    ) {

        require(_startingMaxWalletBps > 0 && _startingMaxWalletBps <= 10_000, "Invalid bps");



        name   = _name;

        symbol = _symbol;

        owner  = msg.sender;



        startingMaxWalletBps = _startingMaxWalletBps;

        growthBpsPerSecond   = _growthBpsPerSecond;

        deployedAt           = block.timestamp;



        uint256 supply        = _totalSupply * (10 ** decimals);

        totalSupply           = supply;

        _balances[msg.sender] = supply;



        // ── Baked-in exemptions ──────────────────────────────────────────────

        // Uniswap V4: PoolManager is the singleton vault — must be exempt.

        // PositionManager + Universal Router may transiently receive tokens.

        // Permit2 handles allowance routing.

        isExempt[V4_POOL_MANAGER]     = true;

        isExempt[V4_POSITION_MANAGER] = true;

        isExempt[V4_UNIVERSAL_ROUTER]  = true;

        isExempt[PERMIT2]             = true;



        // Deployer and this contract are also exempt

        isExempt[msg.sender]    = true;

        isExempt[address(this)] = true;



        emit Transfer(address(0), msg.sender, supply);

        emit OwnershipTransferred(address(0), msg.sender);

    }

constructor(address initialOwner) {
        if (initialOwner == address(0)) {
            revert OwnableInvalidOwner(address(0));
        }
        _transferOwnership(initialOwner);
    }

function upgradeToAndCall(address newImplementation, bytes memory data) public payable virtual onlyProxy {
        _authorizeUpgrade(newImplementation);
        _upgradeToAndCallUUPS(newImplementation, data);
    }

try IERC1822Proxiable(newImplementation).proxiableUUID() returns (bytes32 slot) {
            if (slot != ERC1967Utils.IMPLEMENTATION_SLOT) {
                revert UUPSUnsupportedProxiableUUID(slot);
            }
            ERC1967Utils.upgradeToAndCall(newImplementation, data);
        } catch {
            // The implementation is not UUPS
            revert ERC1967Utils.ERC1967InvalidImplementation(newImplementation);
        }

