constructor(IERC20 token_) ERC20(
        string.concat("lo0pED ", IERC20Metadata(address(token_)).symbol(), "/ETH LP"),
        string.concat("lo",      IERC20Metadata(address(token_)).symbol(), "-ETH")
    ) {
