function commitJudgment(
        uint256 roundId,
        LibArenaStorage.EngineAsset entryAsset,
        LibArenaStorage.Direction direction,
        uint256 amount
    ) external payable returns (uint256 judgmentId) {
        LibArenaStorage.ArenaStorage storage store = _store();
        judgmentId = _commitJudgment(
            store,
            roundId,
            entryAsset,
            direction,
            amount,
            DEFAULT_DATA_QUALITY_TIER,
            DEFAULT_TIER_WEIGHT_BPS
        );
    }

function commitJudgmentWithAutoResolve(
        uint256 roundId,
        LibArenaStorage.EngineAsset entryAsset,
        LibArenaStorage.Direction direction,
        uint256 amount,
        uint256[] calldata autoResolveJudgmentIds
    ) external payable returns (uint256 judgmentId) {
        LibArenaStorage.ArenaStorage storage store = _store();
        _resolveOwnedJudgments(
            store,
            autoResolveJudgmentIds,
            MAX_AUTO_RESOLVE_PER_COMMIT,
            true
        );

        judgmentId = _commitJudgment(
            store,
            roundId,
            entryAsset,
            direction,
            amount,
            DEFAULT_DATA_QUALITY_TIER,
            DEFAULT_TIER_WEIGHT_BPS
        );
    }

function commitJudgmentWithDataQuality(
        uint256 roundId,
        LibArenaStorage.EngineAsset entryAsset,
        LibArenaStorage.Direction direction,
        uint256 amount,
        IAceDataQuality.DataQualityAttestation calldata attestation,
        bytes calldata signature
    ) external payable returns (uint256 judgmentId) {
        LibArenaStorage.ArenaStorage storage store = _store();
        if (store.dataQuality == address(0)) {
            revert InvalidAddress();
        }
        if (attestation.user != msg.sender || attestation.roundId != roundId) {
            revert InvalidDataQualityAttestation();
        }

        (uint8 dataQualityTier, uint16 tierWeightBps) = IAceDataQuality(
            store.dataQuality
        ).consumeAttestation(attestation, signature);

        judgmentId = _commitJudgment(
            store,
            roundId,
            entryAsset,
            direction,
            amount,
            dataQualityTier,
            tierWeightBps
        );
    }

function lockRoundWithOracleData(
        uint256 roundId,
        bytes[] calldata priceUpdateData
    ) external payable {
        _lockRound(roundId, priceUpdateData, msg.value);
    }

function advanceRound(
        uint256 lockRoundId,
        uint256 settleRoundId,
        uint256 nextRoundId,
        bytes[] calldata lockPriceUpdateData,
        bytes[] calldata settlePriceUpdateData,
        bytes[] calldata startPriceUpdateData,
        uint256 lockUpdateFee,
        uint256 settleUpdateFee,
        uint256 startUpdateFee
    ) external payable {
        _enforceSettlementOperator();
        if (
            settleRoundId == 0 ||
            lockRoundId != settleRoundId + 1 ||
            nextRoundId != lockRoundId + 1
        ) {
            revert InvalidRound();
        }

        if (msg.value != lockUpdateFee + settleUpdateFee + startUpdateFee) {
            revert InvalidAmount();
        }

        _lockRound(lockRoundId, lockPriceUpdateData, lockUpdateFee);
        _settleRound(settleRoundId, settlePriceUpdateData, settleUpdateFee);
        _startRound(nextRoundId, startPriceUpdateData, startUpdateFee);
    }

function settleRoundWithOracleData(
        uint256 roundId,
        bytes[] calldata priceUpdateData
    ) external payable {
        _enforceSettlementOperator();
        _settleRound(roundId, priceUpdateData, msg.value);
    }

