      msg.sender,
      shares,
      defiAmount,
      zapToken,
      auth.amount,
      userShares[msg.sender],
      totalShares,
      balanceBefore,
      lastBalance,
      getBaseTokens(),
      baseBalancesBefore,
      getBaseAmounts(lastBalance),
      block.timestamp);
  }

