constructor(
        address crvUsd_,
        address crv_,
        address cvx_,
        address weth_,
        address cvxCrv_,
        address crvUsdWethCrvPool_,
        address cvxWethPool_,
        address crvCvxCrvPool_
    ) {
        crvUsd = crvUsd_;
        crv = crv_;
        cvx = cvx_;
        weth = weth_;
        cvxCrv = cvxCrv_;
        crvUsdWethCrvPool = ICurveCvxCrvCryptoPool(crvUsdWethCrvPool_);
        cvxWethPool = ICurveCvxCrvCryptoPool(cvxWethPool_);
        crvCvxCrvPool = ICurveCvxCrvStablePool(crvCvxCrvPool_);
    }

constructor(address asset_, address stakingWrapper_, address owner_, address feeRecipient_) {
        if (asset_ == address(0) || stakingWrapper_ == address(0) || owner_ == address(0) || feeRecipient_ == address(0)) {
            revert ZeroAddress();
        }

        asset = ERC20(asset_);
        stakingWrapper = ICvxCrvStakingWrapper(stakingWrapper_);
        owner = owner_;
        keeper = owner_;
        feeRecipient = feeRecipient_;
        harvestFeeBps = DEFAULT_HARVEST_FEE_BPS;
        rewardSwapSetters[owner_] = true;
        _setRewardToken(0xD533a949740bb3306d119CC777fa900bA034cd52, true);
        _setRewardToken(0x4e3FBD56CD56c3e72c1403e103b45Db9da5B9D2B, true);
        _setRewardToken(0xf939E0A03FB07F59A73314E73794Be0E57ac1b4E, true);
        _setRewardToken(0x6c3F90f043a72FA612cbac8115EE7e52BDe6E490, true);

        ERC20(asset_).forceApprove(stakingWrapper_, type(uint256).max);
        emit OwnershipTransferred(address(0), owner_);
        emit KeeperSet(owner_);
        emit HarvestFeeConfigSet(DEFAULT_HARVEST_FEE_BPS, feeRecipient_);
        emit RewardSwapSetterSet(owner_, true);
    }

try ICvxCrvRewardSwapExecutor(route.executor).swapExactInput(
            rewardToken, assetAddress, amountIn, route.maxSlippageBps, route.data
        ) returns (uint256) {
            ERC20(rewardToken).forceApprove(route.spender, 0);
        } catch {
            ERC20(rewardToken).forceApprove(route.spender, 0);
            revert RewardSwapFailed(rewardToken);
        }

constructor(address asset_, string memory name_, address allocator_, address adminFeeRecipient_)
        BaseStrategy(asset_, name_)
    {
        if (allocator_ == address(0) || adminFeeRecipient_ == address(0)) revert ZeroAddress();
        allocator = CvxCrvRewardAllocator(allocator_);
        adminFeeRecipient = adminFeeRecipient_;
        withdrawFeeBps = DEFAULT_WITHDRAW_FEE_BPS;
        strategyYieldBoostFeeBps = DEFAULT_STRATEGY_YIELD_BOOST_FEE_BPS;
    }

constructor(address want_, address boostHub_, uint256 pid_, address vault_) Ownable(msg.sender) {
        if (want_ == address(0) || boostHub_ == address(0) || vault_ == address(0)) revert ZeroAddress();
        want = want_;
        boostHub = IBoostHub(boostHub_);
        pid = pid_;
        vault = vault_;
        IERC20(want_).forceApprove(boostHub_, type(uint256).max);
    }

constructor(address asset_, string memory name_, address boostHub_, uint256 pid_, address adminFeeRecipient_)
        BaseStrategy(asset_, name_)
    {
        if (boostHub_ == address(0) || adminFeeRecipient_ == address(0)) revert ZeroAddress();
        boostHub = IBoostHub(boostHub_);
        pid = pid_;
        adminFeeRecipient = adminFeeRecipient_;
        withdrawFeeBps = DEFAULT_WITHDRAW_FEE_BPS;
        strategyYieldBoostFeeBps = DEFAULT_STRATEGY_YIELD_BOOST_FEE_BPS;
        rewardSwapSetters[msg.sender] = true;
        ERC20(asset_).forceApprove(boostHub_, type(uint256).max);
    }

try IRewardSwapExecutor(route.executor).swapExactInput(
                rewardToken, assetAddress, amountIn, route.maxSlippageBps, route.data
            ) returns (uint256) {
                ERC20(rewardToken).forceApprove(route.spender, 0);
            } catch {
                ERC20(rewardToken).forceApprove(route.spender, 0);
                revert RewardSwapFailed(rewardToken);
            }

constructor(address vault_, address strategy_, address owner_) {
        if (vault_ == address(0) || strategy_ == address(0) || owner_ == address(0)) revert ZeroAddress();
        vault = IYearnVaultV3(vault_);
        strategy = strategy_;
        owner = owner_;
