        require(amount > 0, "Zero amount");
        require(totalSupply() + amount <= MAX_SUPPLY, "Sold out");

        uint256 cost;

        if (minted[msg.sender] == 0) {
            if (amount > 1) {
                cost = (amount - 1) * PRICE;
            }
        } else {
            cost = amount * PRICE;
        }

        require(msg.value >= cost, "Not enough ETH");

        minted[msg.sender] += amount;
        _safeMint(msg.sender, amount);
    }

