constructor(address owner_, address royaltyReceiver_, uint96 royaltyBps_, address transferValidator_)
        ERC721OpenZeppelin("Slop Packs", "SLOPPACK")
    {
        if (owner_ == address(0)) {
            revert ZeroOwner();
        }

        if (royaltyReceiver_ != address(0) || royaltyBps_ != 0) {
            _setDefaultRoyalty(royaltyReceiver_, royaltyBps_);
        }

        // `setTransferValidator` is owner-gated; OZ4 `Ownable` sets the owner to
        // `msg.sender` (the deployer) in its constructor, so this call (and the
        // royalty setup above) run as owner BEFORE we hand off below.
        if (transferValidator_ != address(0) && transferValidator_ != getTransferValidator()) {
            setTransferValidator(transferValidator_);
        }

        // Transfer to `owner_` only if it isn't already the deployer.
        if (owner_ != msg.sender) {
            transferOwnership(owner_);
        }
    }

constructor(
        address owner_,
        address minter_,
        address slopToken_,
        address royaltyReceiver_,
        uint96 royaltyBps_,
        string memory baseUri_,
        string memory starvingBaseUri_,
        string memory deadBaseUri_,
        string memory immortalBaseUri_,
        address transferValidator_
    ) ERC721OpenZeppelin("Sloplings", "SLOPLINGS") {
        if (owner_ == address(0)) {
            revert ZeroAddress();
        }
        if (slopToken_ == address(0)) {
            revert ZeroAddress();
        }

        slopToken = ISloplingsSlopToken(slopToken_);
        _setMinter(minter_);
        _setBaseUri(baseUri_);
        _setStateBaseUri(SloplingState.Starving, starvingBaseUri_);
        _setStateBaseUri(SloplingState.Dead, deadBaseUri_);
        _setStateBaseUri(SloplingState.Immortal, immortalBaseUri_);

        if (royaltyReceiver_ != address(0) || royaltyBps_ != 0) {
            _setDefaultRoyalty(royaltyReceiver_, royaltyBps_);
        }

        if (transferValidator_ != address(0) && transferValidator_ != getTransferValidator()) {
            setTransferValidator(transferValidator_);
        }
        if (owner_ != msg.sender) {
            transferOwnership(owner_);
        }
    }

